    for (var i = 0; i < rows.length; i++) {
      var r = rows[i], nm = r.querySelector('.chat-history__item-name');
      idx['c:' + r.id.slice(2)] = { hide: r, drag: r, name: nm ? nm.textContent.trim() : '', icon: iconHtml(r.firstElementChild), html: mirrorHtml(r) };
    }
