        m.querySelector('.aiondx-ctxmenu-read').textContent = fresh ? ctxReading(fresh, compactView({ convId: convId, used: fresh.used })) +(cl ? '\n' + cl : '') : 'No context count yet for this chat (it starts after its first reply).';
