    m.style.left = Math.max(8, Math.min(Math.round(rc.left + rc.width / 2 - 160), window.innerWidth - 330)) + 'px';
    m.style.top = Math.max(8, Math.round(rc.top - m.offsetHeight - 8)) + 'px';
